  const statusBlocked = currentStore.filter(job => job.status !== "READY");
  if (statusBlocked.length) actions.push({ job: statusBlocked[0], next: { priority: 1, label: "商品包待确认", detail: `${statusBlocked.length} 条商品包仍为待审核状态；先填入真实资料并完成卖家页核验，再改为 READY。`, action: "preview" } });
  const duplicate = currentStore.filter(job => job.status === "READY" && duplicateListingDetail(job));
