  if (task.state === "PAUSED" && ["PAUSED_RISK_CONTROL", "RISK_PAUSED"].includes(task.currentStep)) return { priority: 0, label: "先处理风控现场", detail: "请在专用 Chrome 完成滑块、验证码或登录验证，再记录处理结果后恢复；工作台不会代为处理。", action: "resume" };
