  if (task.state === "PAUSED" && ["MAPPING_CHANGED_SINCE_REVIEW", "MAPPING_SNAPSHOT_MISSING"].includes(task.currentStep)) return { priority: 1, label: "字段映射已变化", detail: "任务创建后的映射与当前记录不一致或未冻结；重新逐项核验后取消旧任务，再新建 DRY_RUN。", action: "mapping" };
