  if (task.state === "PAUSED" && task.currentStep === "PAGE_OR_MAPPING_PAUSED") return { priority: 2, label: "页面或字段映射待人工核验", detail: "页面结构或映射定位未能安全执行；查看记录和截图，核验后取消旧任务，再更新真实映射。", action: "mapping" };
  if (task.state === "PAUSED" && task.currentStep === "MANUAL_FIELD_REQUIRED") return { priority: 1, label: "等待人工填写字段", detail: "在卖家页完成当前字段后，确认已人工填写。", action: "acknowledge-manual" };
  if (task.state === "PAUSED" && task.currentStep === "FINAL_REVIEW_REQUIRED") return { priority: 2, label: "等待当前草稿核验", detail: "核对页面、目的地、素材与属性；确认后若有下一条，会回到队列等待再次开始，始终不会发布。", action: "complete-dry-run" };
  if (task.state === "PAUSED") return { priority: 3, label: "任务已暂停", detail: "查看最近记录；非风控暂停须先修复原因、取消旧任务，再新建 DRY_RUN。", action: "detail" };
