  if (task.state === "QUEUED") return model.browser.canExecute ? { priority: 5, label: "已排队，可开始", detail: "当前页面身份已核验；开始时会再次复核。", action: "start" } : { priority: 1, label: "先核验当前草稿页的店铺", detail: model.browser.reason || "浏览器连接不代表身份已核验，请先在店铺会话卡完成核对。", action: "identity" };
