function mappingTemplate() { return { platform: "taobao", version: "", verified_evidence: "", draft_url: "", fields: [{ id: "category", source: "profile.category_path", locator: { strategy: "label", value: "" }, interaction: "manual", reviewed: false }, { id: "title", source: "listing.title", locator: { strategy: "label", value: "" }, interaction: "fill", reviewed: false }, { id: "price", source: "profile.price_cny", locator: { strategy: "label", value: "" }, interaction: "fill", reviewed: false }, { id: "main_images", source: "assets.main_image", locator: { strategy: "css", value: "" }, interaction: "upload", reviewed: false }, { id: "secondary_images", source: "assets.secondary_images", locator: { strategy: "css", value: "" }, interaction: "upload", reviewed: false }, { id: "detail_images", source: "assets.detail_images", locator: { strategy: "css", value: "" }, interaction: "upload", reviewed: false }] }; }
function mappingDraft() { try { const value = JSON.parse($("#mappingJson").value); return value && typeof value === "object" && !Array.isArray(value) ? value : null; } catch { return null; } }
function mappingFieldReady(field) { const locator = field?.locator || {}; return Boolean(String(locator.strategy || "").trim() && String(locator.value || "").trim() && (locator.strategy !== "role" || String(locator.role || "").trim()) && ["fill", "select", "upload", "manual"].includes(field.interaction)); }
function renderMappingChecklist() { const host = $("#mappingChecklist"); host.replaceChildren(); const mapping = mappingDraft(); if (!mapping || !Array.isArray(mapping.fields)) { const note = document.createElement("p"); note.className = "dialog-help"; note.textContent = "映射 JSON 无法解析，暂时不能核验字段。"; host.append(note); return; } const fields = new Map(mapping.fields.filter(field => field?.id).map(field => [field.id, field])); for (const [id, label] of mappingChecklistFields) { const field = fields.get(id), ready = mappingFieldReady(field), reviewed = field?.reviewed === true, manual = field?.interaction === "manual"; const row = document.createElement("label"), checkbox = document.createElement("input"), copy = document.createElement("span"), name = document.createElement("strong"), detail = document.createElement("small"), state = document.createElement("span"); row.className = `mapping-check-item${reviewed ? " reviewed" : manual ? " manual" : !ready ? " blocked" : ""}`; checkbox.type = "checkbox"; checkbox.checked = reviewed; checkbox.disabled = !ready; checkbox.setAttribute("aria-label", `标记${label}已在当前卖家页核验`); name.textContent = label; if (!field) { detail.textContent = "未添加字段"; state.textContent = "待补"; } else if (!ready) { detail.textContent = "需补定位器或交互方式"; state.textContent = "待补"; } else if (reviewed) { detail.textContent = manual ? "人工填写，已确认" : "定位器已确认"; state.textContent = "已核验"; } else { detail.textContent = manual ? "需人工填写后确认" : "已录入，待核验"; state.textContent = manual ? "人工填写" : "待核验"; } copy.className = "mapping-check-copy"; state.className = "mapping-check-state"; copy.append(name, detail); row.append(checkbox, copy, state); checkbox.addEventListener("change", () => { const next = mappingDraft(); const target = next?.fields?.find(candidate => candidate.id === id); if (!target) return; target.reviewed = checkbox.checked; $("#mappingJson").value = JSON.stringify(next, null, 2); $("#mappingError").textContent = ""; renderMappingChecklist(); }); host.append(row); } }
function setMappingCaptureStatus(message, risk = false) { const status = $("#mappingCaptureStatus"); status.textContent = message; status.classList.toggle("is-risk", risk); }
function renderMappingCaptureHistory(job) { const host = $("#mappingCaptureHistory"); host.replaceChildren(); const captures = Array.isArray(job?.mappingCaptures) ? job.mappingCaptures.slice(0, 3) : []; for (const capture of captures) { const row = document.createElement("article"), copy = document.createElement("div"), title = document.createElement("strong"), detail = document.createElement("small"); row.className = `mapping-capture-record${capture.risk ? " risk" : ""}`; title.textContent = capture.risk ? `已记录风险现场：${capture.risk}` : "已记录卖家页证据"; detail.textContent = `${eventTime(capture.capturedAt)} · 仅供人工核验`; copy.append(title, detail); row.append(copy); const href = evidenceHref(capture.evidence); if (href) { const link = document.createElement("a"); link.href = href; link.target = "_blank"; link.rel = "noopener"; link.textContent = "查看截图"; row.append(link); } host.append(row); } }
function openMapping(job) { if (!job) return; $("#mappingJobId").value = job.id; $("#mappingTitle").textContent = `${job.destination} · 字段映射`; const mapping = Object.keys(job.automationMapping || {}).length ? job.automationMapping : mappingTemplate(); $("#mappingJson").value = JSON.stringify(mapping, null, 2); $("#mappingError").textContent = ""; renderMappingCaptureHistory(job); renderMappingChecklist(); setMappingCaptureStatus("尚未记录页面证据。请先在专用 Chrome 手动打开正确的卖家草稿页。"); if ($("#reviewDialog").open) $("#reviewDialog").close(); $("#mappingDialog").showModal(); }
async function captureMappingPage() { const id = $("#mappingJobId").value, button = $("#captureMappingPage"); if (!id) { setMappingCaptureStatus("未找到当前商品包，请关闭窗口后重试。", true); return; } button.disabled = true; setMappingCaptureStatus("正在记录当前专用 Chrome 页面…"); try { const data = await api(`/api/jobs/${encodeURIComponent(id)}/capture-mapping-evidence`, { method: "POST", body: "{}" }), capture = data.capture; model.state = data.state; renderMappingCaptureHistory(data.job); if (capture.risk) { setMappingCaptureStatus(`已保存现场截图，但检测到“${capture.risk}”。请在专用 Chrome 手动完成验证后重新记录；本次不会写入映射。`, true); return; } let mapping; try { mapping = JSON.parse($("#mappingJson").value); } catch { mapping = mappingTemplate(); } const insertedUrl = !String(mapping.draft_url || "").trim(), insertedEvidence = !String(mapping.verified_evidence || "").trim(); if (insertedUrl) mapping.draft_url = capture.url; if (insertedEvidence) mapping.verified_evidence = capture.evidence; $("#mappingJson").value = JSON.stringify(mapping, null, 2); renderMappingChecklist(); setMappingCaptureStatus(`已保存本地页面截图；${insertedUrl || insertedEvidence ? "已填入空白的草稿页地址或证据字段" : "现有映射内容已保留"}。请继续人工核验每个定位器。`); } catch (error) { setMappingCaptureStatus(error.message, true); } finally { button.disabled = false; } }
